Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "background": "transparent",
  "padding": 0,
  "autosize": {
    "type": "none"
  },
  "signals": [
    {
      "name": "pad",
      "value": 6
    }
  ],
  "data": [
    {
      "name": "dataset"
    },
    {
      "name": "tree",
      "source": "dataset",
      "transform": [
        {
          "type": "nest",
          "keys": [],
          "generate": true
        },
        {
          "type": "treemap",
          "field": "Receita Total",
          "sort": {
            "field": "value",
            "order": "descending"
          },
          "round": true,
          "method": "squarify",
          "ratio": 1.4,
          "size": [
            {
              "signal": "width"
            },
            {
              "signal": "height"
            }
          ],
          "paddingInner": {
            "signal": "pad"
          },
          "as": [
            "x0",
            "y0",
            "x1",
            "y1",
            "depth",
            "children"
          ]
        }
      ]
    },
    {
      "name": "leaves",
      "source": "tree",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.depth === 1"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "color",
      "type": "ordinal",
      "domain": [
        "Campeões",
        "Big Spenders (Não-Recorrentes)",
        "Novos / Ocasionais",
        "Em Risco / Hibernando"
      ],
      "range": [
        "#5E6AD2",
        "#BF6FF8",
        "#F2C94C",
        "#E5484D"
      ]
    }
  ],
  "marks": [
    {
      "type": "rect",
      "from": {
        "data": "leaves"
      },
      "encode": {
        "enter": {
          "fill": {
            "scale": "color",
            "field": "Cluster_Name"
          },
          "fillOpacity": {
            "value": 0.62
          },
          "stroke": {
            "scale": "color",
            "field": "Cluster_Name"
          },
          "strokeWidth": {
            "value": 1
          },
          "strokeOpacity": {
            "value": 0.7
          },
          "cornerRadius": {
            "value": 12
          }
        },
        "update": {
          "x": {
            "field": "x0"
          },
          "y": {
            "field": "y0"
          },
          "x2": {
            "field": "x1"
          },
          "y2": {
            "field": "y1"
          },
          "fillOpacity": {
            "signal": "datum.__selected__ === ''off'' ? 0.16 : 0.62"
          },
          "strokeOpacity": {
            "signal": "datum.__selected__ === ''off'' ? 0.25 : 0.7"
          },
          "tooltip": {
            "signal": "{''Segmento'': datum.Cluster_Name, ''Clientes'': replace(format(datum[''Total Clientes''], '',.0f''), '','', ''.''), ''Receita'': ''R$ '' + replace(format(datum[''Receita Total'']/1e6, ''.1f''), ''.'', '','') + '' mi''}"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "leaves"
      },
      "encode": {
        "enter": {
          "fill": {
            "value": "#F4F4F5"
          },
          "font": {
            "value": "Segoe UI"
          },
          "fontSize": {
            "value": 14
          },
          "fontWeight": {
            "value": 600
          },
          "text": {
            "field": "Cluster_Name"
          },
          "baseline": {
            "value": "top"
          }
        },
        "update": {
          "x": {
            "field": "x0",
            "offset": 14
          },
          "y": {
            "field": "y0",
            "offset": 11
          },
          "limit": {
            "signal": "datum.x1 - datum.x0 - 18"
          },
          "fillOpacity": {
            "signal": "(datum.y1 - datum.y0) > 32 && (datum.x1 - datum.x0) > 66 ? 1 : 0"
          },
          "fontSize": {
            "signal": "clamp(min((datum.y1 - datum.y0) * 0.26, 14), 11, 14)"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "leaves"
      },
      "encode": {
        "enter": {
          "fill": {
            "value": "#EDEDEF"
          },
          "font": {
            "value": "Segoe UI"
          },
          "fontSize": {
            "value": 10
          },
          "text": {
            "signal": "replace(format(datum[''Total Clientes''], '',.0f''), '','', ''.'') + '' clientes''"
          },
          "baseline": {
            "value": "top"
          },
          "fontWeight": {
            "value": 600
          },
          "align": {
            "value": "left"
          }
        },
        "update": {
          "x": {
            "field": "x0",
            "offset": 14
          },
          "y": {
            "field": "y0",
            "offset": 30
          },
          "fillOpacity": {
            "signal": "(datum.y1 - datum.y0) > 46 && (datum.x1 - datum.x0) > 90 ? 1 : 0"
          },
          "limit": {
            "signal": "datum.x1 - datum.x0 - 16"
          },
          "fontSize": {
            "signal": "clamp(min((datum.y1 - datum.y0) * 0.18, 12), 10.5, 12)"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "leaves"
      },
      "encode": {
        "enter": {
          "fill": {
            "value": "#F4F4F5"
          },
          "font": {
            "value": "Segoe UI"
          },
          "fontWeight": {
            "value": 700
          },
          "text": {
            "signal": "''R$ '' + replace(format(datum[''Receita Total'']/1e6, ''.1f''), ''.'', '','') + '' mi''"
          },
          "baseline": {
            "value": "bottom"
          }
        },
        "update": {
          "x": {
            "field": "x0",
            "offset": 14
          },
          "y": {
            "signal": "(datum.y1 - datum.y0) > 70 ? datum.y1 - 12 : datum.y1 - 6"
          },
          "fontSize": {
            "signal": "clamp(min((datum.y1 - datum.y0) * 0.28, (datum.x1 - datum.x0) * 0.125, (datum.y1 - datum.y0) - 42), 12, 24)"
          },
          "limit": {
            "signal": "datum.x1 - datum.x0 - 12"
          },
          "fillOpacity": {
            "value": 1
          }
        }
      }
    }
  ]
}'
